crates/domain/change/src/
  lib.rs                 pub use だけ
  verdict.rs             値オブジェクト 検証結果（validation ・ render ・ search も使う）
  instance_state.rs      インスタンスの状態の4つ（I19：保存せず、検証結果と判定の記録から導く）
  change_item.rs         値オブジェクト 変更の項目
  judgment/              集約 判定の記録
    mod.rs               ルートとコマンド（使い直すか I16）
    judged_values.rs     値オブジェクト 判定した値（この集約だけが使う）
  change_record/         集約 変更の記録
    mod.rs               ルートとコマンド（書き換えない I32）
    meaning.rs           値オブジェクト 意味（I33）
  summary/               変更のまとまりの形と、そのファクトリ（記録から機械的に作る I35）
    mod.rs

// change_record/mod.rs
pub struct ChangeRecord {
    id: ChangeRecordId,      // private：外からは読むだけ
    intent: Intent,
    items: Vec<ChangeItem>,
}
impl ChangeRecord {
    /// 不変条件 I37：id は書いた時に1回だけ決め、あとから変えない
    pub fn record(id: ChangeRecordId, intent: Intent, items: Vec<ChangeItem>) -> Self { /* … */ }
    pub fn items(&self) -> &[ChangeItem] { &self.items }
}

